// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(bytes32 hash1, bytes32 hash2, address actor) public {
        vm.assume(actor != address(0));
        vm.deal(actor, 10 ether);

        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash1);

        vm.prank(actor);
        bool secondCallSucceeded;
        try c.lockInGuess{value: 1 ether}(hash2) {
            secondCallSucceeded = true;
        } catch {
            secondCallSucceeded = false;
        }

        assertFalse(secondCallSucceeded);
    }
}
